const NAV: NavItem[] = [
  { id: 'home', label: 'Home', icon: <House size={NAV_ICON_SIZE} /> },
  {
    id: 'finance',
    label: 'Finance',
    icon: <Wallet size={NAV_ICON_SIZE} />,
    badge: { kind: 'count', value: 12, tone: 'info' },
  },
  {
    id: 'reports',
    label: 'Reports',
    icon: <FileText size={NAV_ICON_SIZE} />,
    children: [
      { id: 'reports-scheduled', label: 'Scheduled reports', icon: <CalendarClock size={NAV_ICON_SIZE} /> },
      { id: 'reports-archive', label: 'Report archive', icon: <Archive size={NAV_ICON_SIZE} /> },
    ],
  },
  {
    kind: 'section',
    id: 'connect',
    label: 'Connect',
    items: [
      { id: 'devices', label: 'Devices', icon: <HardDrive size={NAV_ICON_SIZE} /> },
    ],
  },
]

const SECTION_DEFAULTS = { reports: 'reports-scheduled' }

<IosenseShell
  navItems={NAV}
  logo={<YourLogo />}
  activeId={activeId}
  onNavigate={(id) => setActiveId(resolveSection(id, SECTION_DEFAULTS))}
  trail={buildTrail(activeId, title, { items: NAV, pageTitles: PAGE_TITLES })}
  {...rest}
>
  <YourPage />
</IosenseShell>

// NavFooterRow, not a bare IconButton: the label then fades in when the rail
// opens and drops to the icon alone in the 48px strip, like every other row.
<IosenseShell
  sideNavFooter={
    <NavFooterRow icon={<CircleQuestionMark size={NAV_ICON_SIZE} />} label="Help" onClick={openHelp} />
  }
  {...rest}
/>
